import clsx from 'clsx';
import React, { forwardRef, useMemo } from 'react';

import {
  calendarButtonCSS,
  currentIndicator,
  outOfScopeDay,
} from './CalendarItem.sty.js';
import type { _CalendarViewType } from './types/shared-types.js';
import { Button } from '../../../buttons/button/Button.js';
import { _useFormFieldContext } from '../../forms-core/hooks/useFormFieldContext.js';

//#region types
/** @internal */
export interface CalendarButtonProps
  extends React.ComponentPropsWithRef<'div'> {
  /** Controls the disabled state. */
  disabled?: boolean;
  /** Whether the calendar button is focused. */
  focused?: boolean;
}

type CalendarDayButtonProps = {
  isCurrentMonthDay?: boolean;
  isOnlySelected?: boolean;
};

/** @internal */
export interface ViewItem {
  /** The localized aria label of the view item. */
  ariaLabel: string;
  /** The tabindex attribute of the view item. */
  tabIndex: 0 | -1;
  /** Whether this is the current view item (i.e. today, current month, current year). */
  isCurrent: boolean;
  /** Whether the item is disabled. */
  isDisabled?: boolean;
  /** Color used for the highlighting. */
  highlightColor?: 'neutral' | 'primary' | 'critical';
  /** Whether the view item is actually selected. */
  isSelected?: boolean;
  /** Event listener for clicks on the view item. */
  onClick: (
    event?:
      | React.MouseEvent<HTMLDivElement>
      | React.KeyboardEvent<HTMLDivElement>,
  ) => void;
  /** Event listener for complex hover styles on range selection. */
  rangeInteractionProps?: {
    onMouseEnter?: React.MouseEventHandler<HTMLElement>;
    onMouseLeave?: React.MouseEventHandler<HTMLElement>;
  };
  /** How the item should be highlighted. */
  highlightType?: 'first' | 'last' | 'inbetween' | 'same';
  /** What kind of selection outline should be used. */
  selectionVariant?:
    | 'absolute'
    | 'relative'
    | 'absolute-relative'
    | 'relative-absolute';
}

/** @internal */
export type CalendarItemProps = ViewItem &
  CalendarButtonProps & {
    isInRange?: boolean;
    view: _CalendarViewType;
  } & CalendarDayButtonProps;
//#endregion

export const CalendarItem = /* @__PURE__ */ forwardRef(
  (
    {
      children,
      isCurrent = false,
      highlightColor = 'neutral',
      onClick,
      isSelected = false,
      isDisabled = false,
      isCurrentMonthDay = true,
      view,
      ariaLabel,
      ...remainingProps
    }: CalendarItemProps,
    ref: typeof remainingProps.ref,
  ) => {
    const { disabled } = _useFormFieldContext();

    const variant = useMemo(() => {
      // The day doesn't rely on the button background color styles.
      if (view === 'day') {
        return 'default';
      }

      if (isSelected) {
        return 'accent';
      }

      if (isCurrent) {
        return 'emphasized';
      }

      return 'default';
    }, [view, isSelected, isCurrent]);

    const currentStyle = view !== 'day' && isCurrent ? currentIndicator : '';

    const selectionHandler =
      !isDisabled && !disabled
        ? {
            onClick,
            onKeyDown: (event: React.KeyboardEvent<HTMLDivElement>) => {
              const { code } = event;

              if (code === 'Space' || code === 'Enter') {
                onClick?.(event);
              }
            },
          }
        : {};

    return (
      <Button
        as="div"
        ref={ref}
        data-testid="calendar-body-date-button"
        aria-label={ariaLabel}
        {...remainingProps}
        className={clsx(calendarButtonCSS, currentStyle, {
          [outOfScopeDay]: !isCurrentMonthDay && highlightColor === 'neutral',
        })}
        color={highlightColor}
        disabled={disabled || isDisabled}
        aria-disabled={disabled || isDisabled}
        variant={variant}
        {...selectionHandler}
      >
        {children}
      </Button>
    );
  },
);
(
  CalendarItem as typeof CalendarItem & {
    displayName: string;
  }
).displayName = 'CalendarBodyDateButton';
